body:
I combined V12s masks with a MUL fix in a /tmp core. With this exact change, the whole 81-kernel A32 corpus passes except the genuinely missing V17 VFP class (all k_f*/k_d* stop at vmov/ee000a10). No other stop.

case 0:
  if ((insn & 0x90u) == 0x90u) {
      unsigned lo = (insn >> 4) & 0xFu;
      if (lo == 0xBu || lo == 0xDu || lo == 0xFu ||
          (lo == 0x9u && ((insn >> 8) & 0xFu) == 0xFu))
          return n2a32_arm_mem;
  }
  op = (insn >> 20) & 0x1Fu;
  if ((op & 0x10u) != 0) {
      hi = op & 0xFu; op2 = (insn >> 4) & 0xFu;
      if (((insn >> 23) & 0x1Fu) == 0x02u) {   /* QADD/SMLA family only */
          if (op2 == 5u) return n2a32_arm_media;
          if (op2 == 8u || op2 == 0xAu || op2 == 0xCu || op2 == 0xEu) return n2a32_arm_media;
      }
      if ((insn & 0x0FF000F0u) == 0x01200070u) return n2a32_arm_misc;
      if (hi == 2u && ...) return n2a32_arm_misc;
      return n2a32_arm_dp;
  }
  return n2a32_arm_dp;

case 1: if ((insn & 0x0FFFFF00u) == 0x0320F000u) return n2a32_arm_misc;  /* WFE e320f002 etc. */
case 3: UDF mask first; then if ((insn & 0x10u) != 0) arm_media else arm_mem;  /* LDR/STR reg with P=0 e6901002 */

The `lo==9 && bits11-8==F` test excludes MUL/MLA/SWP (e0010291/e0213291/e1031092) which V12s simpler mask would send to arm_mem. Tmp binary: /tmp/n2hw-T01/exp2/run0/diffrun5, log5. Repro log lines: every k_f* stop=2 insn=ee000a10; everything else returns values identical to the host reference for seeds 0,1,2.
